import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, it, expect } from "vitest";
import { readZip, UnsupportedZipError } from "../src/zip.js";

/**
 * The zip reader is dependency-free, which means its correctness is ours rather
 * than a library's. The fixtures are real Theme Builder exports, regenerated by
 * `apps/marketing/scripts/cli-fixtures.test.ts` through the builder's own code:
 *
 * - `kitchen-sink-teal-theme.zip` is exactly what the Export tab downloads:
 *   JSZip's default, STORE, with each entry's sizes in its local header.
 * - `kitchen-sink-teal-theme-deflate.zip` holds the same files DEFLATE-compressed
 *   with data descriptors, the shape a streaming archiver writes when someone
 *   re-zips the folder. Its local headers carry zeroed sizes and the real ones
 *   are only in the central directory, so a reader that trusts the local header
 *   returns empty files with no error at all. It exercises the inflate path and
 *   the central-directory sizes; the first fixture exercises neither.
 */

const FIXTURE = join(import.meta.dirname, "fixtures", "kitchen-sink-teal-theme.zip");
const DEFLATED = join(import.meta.dirname, "fixtures", "kitchen-sink-teal-theme-deflate.zip");
const archive = readFileSync(FIXTURE);
const deflated = readFileSync(DEFLATED);

/** Each central-directory entry's general-purpose flags and compression method. */
function centralEntries(buffer: Buffer): { flags: number; method: number }[] {
  const out: { flags: number; method: number }[] = [];
  for (let i = 0; i + 4 <= buffer.length; i++) {
    if (buffer.readUInt32LE(i) !== 0x02014b50) continue;
    out.push({ flags: buffer.readUInt16LE(i + 8), method: buffer.readUInt16LE(i + 10) });
  }
  return out;
}

describe("readZip", () => {
  it("reads every entry of a real Theme Builder bundle", () => {
    const entries = readZip(archive);
    expect(entries.map((e) => e.name).sort()).toEqual([
      "README.md",
      "fonts.ts",
      "icons.ts",
      "theme.css",
      "theme.json",
    ]);
    for (const entry of entries) expect(entry.data.length).toBeGreaterThan(0);
  });

  it.each([
    ["stored", FIXTURE],
    ["deflated", DEFLATED],
  ])("produces byte-identical output to unzip(1) (%s)", (_shape, fixture) => {
    // The strongest available oracle: the reference implementation everyone else
    // uses. Skipped where `unzip` isn't installed rather than silently weakened.
    let dir: string;
    try {
      dir = mkdtempSync(join(tmpdir(), "uiorg-zip-"));
      execFileSync("unzip", ["-q", fixture, "-d", dir], { stdio: "ignore" });
    } catch {
      return;
    }
    try {
      const mine = new Map(readZip(readFileSync(fixture)).map((e) => [e.name, e.data]));
      const theirs = readdirSync(dir);
      expect(theirs.sort()).toEqual([...mine.keys()].sort());
      for (const name of theirs) {
        expect(mine.get(name), name).toEqual(readFileSync(join(dir, name)));
      }
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  it("reads DEFLATE entries sized only by the central directory", () => {
    // Prove the fixture still has the shape this test is for: a regeneration
    // that quietly fell back to STORE would make it a copy of the first.
    const shapes = centralEntries(deflated);
    expect(shapes).toHaveLength(5);
    for (const { flags, method } of shapes) {
      expect(method).toBe(8); // deflate
      expect(flags & 0x8).toBe(0x8); // sizes in a data descriptor, zeroed in the local header
    }

    const stored = new Map(readZip(archive).map((e) => [e.name, e.data]));
    const inflated = readZip(deflated);
    expect(inflated.map((e) => e.name).sort()).toEqual([...stored.keys()].sort());
    for (const entry of inflated) expect(entry.data, entry.name).toEqual(stored.get(entry.name));
  });

  it("parses the same content when the archive is read twice", () => {
    expect(readZip(archive)).toEqual(readZip(archive));
  });

  it("names the problem rather than mis-parsing a non-zip", () => {
    expect(() => readZip(Buffer.from("this is not a zip file, it is prose"))).toThrow(
      UnsupportedZipError,
    );
    expect(() => readZip(Buffer.alloc(4))).toThrow(/too small/);
  });

  it("rejects a truncated archive instead of returning partial data", () => {
    // Silently returning half a theme would be worse than failing.
    expect(() => readZip(archive.subarray(0, Math.floor(archive.length / 2)))).toThrow(
      UnsupportedZipError,
    );
  });
});
